    public virtual float3 ComputeHairLightingSpecular(SurfaceData surfaceData, float3 halfVector, float3 toLightVec)
    {
        // modulate specular shift by a texture
        float shiftAngle1 = default;
        float shiftAngle2 = default;
        CalculateShiftAngles(surfaceData, out shiftAngle1, out shiftAngle2);

        float hairSpecularExponent1 = surfaceData.hairSpecularExponent1;
        // We already make sure on the CPU side that "surfaceData.hairSpecularExponent1" can't be "0.0".
        float hairSpecularExponent2 = surfaceData.hairSpecularExponent2;

        // We already make sure on the CPU side that "surfaceData.hairSpecularExponent2" can't be "0.0".
        float3 specular1;
        float3 specular2;
        if (ShadingModel == HAIR_SHADING_KAJIYAKAY_SHIFTED)
        {
            // primary highlight: reflected direction shift towards tip
            specular1 = ComputeSpecularKajiya(surfaceData, toLightVec, shiftAngle1, surfaceData.hairSpecularScale1, hairSpecularExponent1, surfaceData.hairSpecularColor1);
            // secondary highlight: reflected direction shifted toward root
            specular2 = ComputeSpecularKajiya(surfaceData, toLightVec, shiftAngle2, surfaceData.hairSpecularScale2, hairSpecularExponent2, surfaceData.hairSpecularColor2);
        }
        else
        {
            // specular terms
            specular1 = ComputeSpecularScheuermann(surfaceData, halfVector, shiftAngle1, surfaceData.hairSpecularScale1, hairSpecularExponent1, surfaceData.hairSpecularColor1);
            specular2 = ComputeSpecularScheuermann(surfaceData, halfVector, shiftAngle2, surfaceData.hairSpecularScale2, hairSpecularExponent2, surfaceData.hairSpecularColor2);
        }

        // modulate secondary specular term with noise
        specular2 *= surfaceData.hairSecondarySpecularGlintsNoise;

        float3 specular = (specular1 + specular2) * hairShadowingFunction.Compute();
        // Used to apply shadowing/scattering.
        return specular * surfaceData.cavity;
    }

    public virtual float3 ComputeSpecularIndirectLighting(SurfaceData surfaceData, float shiftAngle, float3 specularColor)
    {
        float3 shiftedNormal = Sdsl.Const(ShiftTangent(surfaceData.WBinormal, surfaceData.WNormal, shiftAngle));

        // specular term
        float shiftedNdotV = Sdsl.Const(max(dot(shiftedNormal, surfaceData.WViewDir), 0.0f));

