        float shiftAngle2 = default;
        CalculateShiftAngles(surfaceData, out shiftAngle1, out shiftAngle2);

        float3 specular1 = ComputeSpecularIndirectLighting(surfaceData, shiftAngle1, surfaceData.hairSpecularColor1);
        float3 specular2 = ComputeSpecularIndirectLighting(surfaceData, shiftAngle2, surfaceData.hairSpecularColor2);

        specular1 *= surfaceData.hairSpecularScale1;
        // TODO: This is a workaround to make the indirect lighting look better. Not sure if we should keep it as it basically scales the specular reflection like it does for the direct lighting.
        specular2 *= surfaceData.hairSpecularScale2;
        // TODO: This is a workaround to make the indirect lighting look better. Not sure if we should keep it as it basically scales the specular reflection like it does for the direct lighting.

        // modulate secondary specular term with noise
        specular2 *= surfaceData.hairSecondarySpecularGlintsNoise;

        return specular1 + specular2;
    }

    public override float3 ComputeDirectLightContribution()
    {
        if (DebugRenderPasses)
        {
            return 0.0f;
            // Return 0.0 because the indirect lighting function already returns the debug color.
        }

        float3 specular = ComputeHairLightingSpecular(surfaceData, streams.H, streams.lightDirectionWS);

        // Vector pointing from the pixel towards the light.
        float NdotLUnsaturated = Sdsl.Const(dot(normalize(streams.normalWS), normalize(streams.lightDirectionWS)));
        // TODO: PERFORMANCE: Normalization necessary?

        //specular *= saturate(NdotLUnsaturated * 0.5 + 0.5);   // This could be used in combination with hair SSS.
        specular *= HairSpecularAttenuation(NdotLUnsaturated);
        specular *= hairLightAttenuationFunction.Compute();
        specular *= streams.lightColor * streams.lightAttenuation * streams.matDiffuseSpecularAlphaBlend.y;
        //specular *= streams.lightDirectAmbientOcclusion;

        // TODO: Multiply by alpha or not?
        return specular * streams.matDiffuse.a;
        // TODO: Technically we should use "streams.shadingColorAlpha" but its value is assigned AFTER the shading, which makes it useless.
    }

